"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"เขาว่ากันว่าถ้ากระโดดลงเหมืองจะไปโผล่ที่ฐานศัตรู ไม่ลองหรอกนะ",
"The Swarm painted their visors red again. Show-offs.":"ฝูงแมลงทาไวเซอร์เป็นสีแดงอีกแล้ว สายโชว์จริงๆ",
