"Autosaved":"บันทึกอัตโนมัติแล้ว",
"robot war · the sky is a portal":"สงครามหุ่นยนต์ · ท้องฟ้าคือประตูมิติ",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"ยินดีต้อนรับสู่อุกกาบาต! คุณคือหุ่นยนต์ต่อสู้ของกลุ่มคอนซอร์เทียม มองรอบๆ ด้วยเมาส์แล้วเดินด้วย WASD",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"เจ็ตแพ็ก: กด Shift เบาๆ เพื่อกระโดด กด Shift ค้างเพื่อบิน พลังงานฟื้นเมื่อลงพื้น",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"ยิง — คลิกซ้าย เล็ง — คลิกขวา: แม่นขึ้นและซูมได้ ลองยิงสักสองสามนัด",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"รีโหลด — R กระสุนแรงที่สุดในระยะกลาง 20–50 เมตร",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"จรวด — Q ใช้ต่อรถถังและอาคาร ลองยิงจรวดดู",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"ด้านบนคือภารกิจจากนักยุทธศาสตร์ วิ่งตามลูกศรสีเขียว: บนเส้นทางคุณจะวิ่งสปรินต์ได้ ยึดจุดครอง — ยืนใกล้สัญญาณ",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"หมู่ของคุณคุ้มหลังให้: ภาพและพลังชีวิตของพวกเขาอยู่ทางซ้าย ถ้าตามไม่ทัน พวกเขาจะขอให้คุณรอ",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — สลับตัวละครด่วนโดยไม่ต้องออกจากการรบ: กระโดดเข้าหมู่หรือรถถังที่อยู่ใกล้การปะทะที่สุด ลองดู",
"Next to a tank or turret press E to take control. Or just carry on.":"ข้างรถถังหรือป้อมปืนให้กด E เพื่อควบคุม หรือจะเดินต่อไปก็ได้",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"ถึงเวลาวางแผนแล้ว แตะ \"◩ ยุทธศาสตร์\" ที่มุมขวาบน — มุมมองจากด้านบนของสมรภูมิ",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"ถึงเวลาวางแผนแล้ว กด {0} (หรือ \"◩ ยุทธศาสตร์\" ที่มุมซ้ายบน) — มุมมองจากด้านบนของสมรภูมิ",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"ในโหมดยุทธศาสตร์ ผู้แนะนำจะช่วยคุณ: กล่องด้านบนบอกว่าต้องทำอะไร กรอบชี้ปุ่ม วงแหวนชี้จุดบนแผนที่ ทำตามคำแนะนำให้ครบสามข้อ",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"เลือกหมู่แล้วแตะปุ่มสีเขียว \"▶ สิงร่าง\" — กลับเข้าสู้ในร่างทหารนายนั้น ระหว่างที่คุณยิง นักยุทธศาสตร์ AI จะคุมกองทัพเอง",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"เลือกหมู่แล้วกด {0} หรือปุ่มสีเขียว \"▶ สิงร่าง\" — กลับเข้าสู้ในร่างทหารนายนั้น (ไม่เลือกอะไร — เข้าร่างของตัวเอง) ระหว่างที่คุณยิง นักยุทธศาสตร์ AI จะคุมกองทัพเอง",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"ฝึกซ้อมจบแล้ว! ฝูงแมลงเริ่มบุกแล้ว ขอให้โชคดี ทหาร!",
