"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"แร่หน้าตาใหม่: เส้นแร่เป็นคริสตัลมรกตเจียระไนเรืองแสงบนหินบะซอลต์ดำ มีประกายไฟและหมอกสีเขียว; เครื่องขุดแร่เป็นแท่นหกเหลี่ยม โดมรังผึ้ง และหอโครงข่ายที่มีไฟสัญญาณสีเขียวบนยอด (แถบและธงเป็นสีทีม)",
"New in v6.1":"ใหม่ใน v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"เลือกคลาสโปรดแบบ Battlefield (U, ตัวเลขหลังตาย): เกิดใหม่ในคลาสนั้นเมื่อมีให้ใช้",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"ยานรบมุมมองบุคคลที่หนึ่ง (V — ภายนอก/ในห้องนักบิน); ช่วยเล็งแบบนุ่มนวล — ในตั้งค่า",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"ออกจากแกนกลางง่ายขึ้น: Space — ไปที่ปล่อง, B — แคปซูลขึ้นสู่พื้นผิว; ผลของความสามารถรีเซ็ตเมื่อตาย",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"ความก้าวหน้าไม่สิ้นสุด: นายพลและจอมพล ★, เลเวลอาชีพ, ความชำนาญอาวุธและอุปกรณ์เสริม, เหรียญตรา, สัญญารายวัน — หน้าจอเส้นทางอาชีพ",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"กลยุทธ์: ซูมลื่นไหลด้วยล้อเมาส์ ไอคอนและป้ายชื่อเหนือยูนิต (Alt — แสดงทั้งหมด) แผง \"กำลังพล / อาคาร\" ทางซ้าย",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"คลิกขวา — เดินทัพพร้อมสู้ระหว่างทาง, คลิกขวา 2 ครั้ง — เดินทัพยิงขณะเคลื่อนที่; คำสั่งที่ใช้น้อยอยู่ใน \"คำสั่งอื่น ๆ ▾\"; ปุ่มไม่ซ้ำกัน",
"New in v6":"ใหม่ใน v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"ปืนระดับเกมยิง: กระสุนถึงเป้าทันที ปืนเล็ก 720 นัด/นาที ปืนกล แรงสะท้อน เล็งด้วยคลิกขวา แมกกาซีนและรีโหลดด้วย R เครื่องหมายโดนเป้า",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"แรงโน้มถ่วงหนักขึ้น ประตูเจ็ตตอบสนองไว พุ่งตัวด้วย Z หรือกดเจ็ต 2 ครั้งกลางอากาศ; อาวุธไม่ลอยตามไปตอนสลับยูนิตอีกแล้ว",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"ช่างก่อสร้าง: เลือกช่างก่อสร้าง เลือกอาคาร วางพิมพ์เขียว; Extractor บนเส้นแร่; คลิก \"แร่\" เพื่อดูรายได้และวิธีเพิ่ม",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"ปุ่มสีเทาบอกเหตุผลและเสนอวิธีแก้; ปุ่มใหญ่ขึ้น แถบ \"กำลังดำเนินการ\" \"▶ ควบคุม\" Tab คือปุ่มเดียวสำหรับสลับโหมด",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"กล้องโหมดกลยุทธ์ไม่กระตุกไม่พลิก ซูมเข้าหาเคอร์เซอร์ ลากมินิแมปได้",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"ยานพาหนะใหม่: รถจู่โจม \"Jackal\", รถยิงจรวดหลายลำกล้อง \"Grad\" (จรวดนำวิถี), ปืนครก \"Hammer\"; Swarm ได้ \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"AI strategist จำคำสั่งไว้และไม่รัวเสียง; การรบเกิดใกล้คุณ; B — ย้ายกำลัง, Shift+B — เข้าสู่การรบ; เข็มทิศ, H — เลือกเป้าหมาย",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"เล่นอิสระ (K) และลุยเดี่ยว (J), F2 — พรีเซ็ต; Esc หยุดและเล่นต่อ; เซฟ: สล็อต ส่งออกและนำเข้าไฟล์",
"New in v5.3":"ใหม่ใน v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"การบิน: แรงโน้มถ่วงแรงขึ้นเมื่ออยู่ไกลจากอุกกาบาต C กลางอากาศ — เบรก แรงขับเลี้ยวคมขึ้น; ไม่ลอยติดในประตูมิติอีกแล้ว",
"New in v5":"ใหม่ใน v5",
"Endless war by default and battle scale: normal, large, epic":"สงครามไม่รู้จบเป็นค่าเริ่มต้น และขนาดการรบ: ปกติ ใหญ่ มหากาพย์",
