"Squadmates with callsigns: portraits, health and live chatter":"เพื่อนร่วมหมู่พร้อมรหัสเรียก: ภาพเหมือน พลังชีวิต และบทสนทนาสด",
"Fog of war in strategy, friends and foes outlined differently":"หมอกสงครามในโหมดกลยุทธ์ เพื่อนและศัตรูเรืองแสงต่างกัน",
