"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"ระเบิดมือเด้งและกลิ้งลงตามทางลาด ระเบิดใน 2.5 วิ; มี 2 ลูก ฟื้นฟู 9 วิ; ไอคอนเตือนเมื่อมีระเบิดศัตรูอยู่ใกล้",
