"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — กดค้าง: เห็นวิถีโค้งและวงระเบิด ปล่อยเพื่อขว้าง ระเบิดใน 2.5 วิ มี 2 ลูก",
