"Panel":"แผง",
"Battle":"ลุยเลย",
"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"พลปืนหนักของคอนซอร์เทียมตอนนี้เป็นโมเดล 3D จริงที่มีโครงกระดูก: ยืนนิ่ง เดิน วิ่งพร้อมอาวุธ ยิงขณะเคลื่อนที่ และล้มเมื่อถูกทำลาย",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"โมเดลยืนตามแนวตั้งฉากกับพื้นผิวอุกกาบาต หมุนลำตัวตามเป้าเล็ง และถือปืนกลไว้ในมือ ระยะไกลแอนิเมชันอัปเดตน้อยลง FPS จึงไม่ตก",
"New in v6.5":"สิ่งใหม่ใน v6.5",
"Barracks":"ค่ายทหาร",
"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"ทหารราบ: หมู่จู่โจม พลปืนหนัก พลซุ่มยิง พลสอดแนม ยานลงจอด; การอัปเกรดเกราะและอาวุธ",
"Ore depot":"คลังแร่",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"วิศวกรส่งคริสตัลที่นี่ วางไว้ข้างลานคริสตัล — เดินทางสั้นลง ได้แร่มากขึ้น",
"Tanks and vehicles. Requires Barracks.":"รถถังและยานพาหนะ ต้องมีค่ายทหาร",
"Autonomous combat drones. Requires Barracks.":"โดรนรบอัตโนมัติ ต้องมีค่ายทหาร",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"เจ็ตแพ็ก II และทหารท้องฟ้า (หน่วยเอลีตเจ็ตแพ็ก) ต้องมีโรงงานเมค ปลดล็อกเมื่อถึง 6:00",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"ฐานสำรองที่จุดของฝ่ายเรา: วิศวกร ส่งคริสตัล เสริมกำลัง",
