"Voice of hints & curator":"เสียงคำแนะนำและผู้แนะนำ",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"มือถือ: จอยสติ๊กสามโหมด ซ้ายอย่างเดียว — \"อัตโนมัติ\" (แม่เหล็กแรง แต่กระสุนอ่อนลง) ขวาอย่างเดียว — เปิดการเล็งเอง แม่เหล็กแรงขึ้น ยิงแม่นขึ้น ทั้งสองข้างพร้อมกัน — ไม่มีการเล็ง แม่เหล็กและความแม่นลดลง ปุ่ม 👁 ด้านขวา — ซ่อน/คืนส่วนติดต่อผู้ใช้",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"มือถือ: กลยุทธ์แบบง่าย — เหลือแค่วิศวกรและอาคาร การ์ดทางซ้าย (วิศวกร กองบัญชาการ ค่ายทหาร…): แตะ — กล้องบินไปที่นั่น แถบล่างแสดงสิ่งที่สร้าง/ผลิตได้ \"ลุยสนามรบ\" — ซ้ายบน กองทัพสู้เอง กลยุทธ์เต็มรูปแบบ — ตั้งค่า → มือถือ",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"การควบคุมยูนิต — สวิตช์สองอัน: \"หมู่\" และ \"ยานพาหนะ\" (บนมือถือ ยานพาหนะปิดไว้เป็นค่าเริ่มต้น — AI เป็นคนขับ) ถ้าปิดยานพาหนะ กด E (บนมือถือ — ปุ่มด้านขวา) ข้างยานฝ่ายเดียวกัน — ไปคุมปืนของยาน: ยานขับเอง คุณยิง \"ลำดับคลาสแบบกำหนดเอง\" แบบเก่าอยู่ใน \"ขั้นสูง\" เมื่อควบคุมยูนิต ยูนิตจะตอบกลับทางวิทยุ",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"คำแนะนำอัจฉริยะ: คำแนะนำพื้นฐานจะดับเองหลังเปิดเกมครั้งที่ 2 แต่เกมจะบอกใบ้ฟีเจอร์ที่คุณยังไม่เคยใช้ สวิตช์: พื้นฐาน / ขั้นสูง / หายาก และแยกต่างหากสำหรับเสียงคำแนะนำและผู้แนะนำ",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"รีเฟล็กซ์ชาร์จจากการสังหาร (สังหารต่อเนื่องชาร์จได้มากกว่า) เพื่อนร่วมหมู่ตกหลังหรือตาย — นักยุทธศาสตร์ AI จะส่งคนใหม่ลงมาหาคุณ (แพงกว่าการเสริมกำลังปกติ) รวมกราฟิกและเสียง v7.2gfx แล้ว: ระเบิดเป็นกลุ่มควัน ควัน เศษซาก เสียงสะท้อนในปล่องและปล่องหลุม วันที่บิลด์เป็นของจริงแล้ว",
