"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"เส้นทางอาชีพและเซฟจะไม่ถูกแตะต้อง ในการรบ เมนูเดียวกันคือปุ่ม \"🛠 เมนู\" ที่มุมขวาบน{0}",
"New developer match":"แมตช์นักพัฒนาใหม่",
"all unlocked, endless ore, instant build, arsenal":"ปลดล็อกทุกอย่าง แร่ไม่จำกัด สร้างทันที คลังอาวุธ",
"Trainings — all 4":"ฝึกซ้อม — ครบ 4 บท",
"PC and phone (strategy and shooter)":"PC และมือถือ (กลยุทธ์และนักยิง)",
"Cinema: split screen":"โหมดภาพยนตร์: แบ่งหน้าจอ",
"strategist bot left, shooter bot right":"บอทนักยุทธศาสตร์อยู่ซ้าย บอทนักยิงอยู่ขวา",
