"both bases built and upgraded — for footage":"สร้างและอัปเกรดทั้งสองฐานครบแล้ว — สำหรับถ่ายฟุตเทจ",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"โหมดโรงหนัง — แบ่งหน้าจอ: ซ้ายเป็นบอทนักยุทธศาสตร์ (มุมมองจากด้านบนของฐานและกองทัพ) ขวาเป็นบอทนักยิงมุมมองบุคคลที่หนึ่ง ปุ่มด้านล่าง (คีย์ S, P): \"แบ่งหน้าจอ\" และ \"★ สร้างครบแล้ว\" — สร้างและอัปเกรดทั้งสองฐานครบสำหรับถ่ายฟุตเทจ",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"แกนกลางและอุโมงค์ที่ทะลุอุกกาบาตหายไปแล้ว — อุกกาบาตเป็นก้อนตัน การต่อสู้เกิดขึ้นบนพื้นผิวเท่านั้น",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"มือถือ: 👁 ซ่อน HUD แต่ยังคงเจ็ตแพ็ก, ⇆, จอยสติ๊ก และเครื่องหมายภารกิจไว้ \"◎ เล็ง\" (นิ้วขวาเท่านั้น) — แม่เหล็กช่วยเล็งแรงและกว้างขึ้นชัดเจน ปรับแรงแม่เหล็กของทั้งสามโหมดได้ที่ ตั้งค่า → การควบคุม → \"ขั้นสูง\" เมื่อประจำปืนของยานพาหนะ ปุ่มจะเป็น \"ลงจากปืน\"",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"ฝึกซ้อม: มือถือแสดงเฉพาะบทฝึกของมือถือ ส่วน PC แสดงเฉพาะของ PC ทั้ง 4 บทอยู่ในเมนู \"🛠 นักพัฒนา\" โหมดนักพัฒนากับคลังอาวุธรวมเป็นเมนูเดียวกันแล้ว (ในการรบ — \"🛠 เมนู\" มุมขวาบน, บน PC กด F8)",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"สไตล์กราฟิก \"Dendy (8-bit)\" และ \"16-bit\": ตั้งค่า → กราฟิก → \"สไตล์กราฟิก\" (รายละเอียด — ปุ่ม ⚙) ถ้า FPS ต่ำกว่า 24 ในช่วง ~10 วินาทีแรกของแมตช์ Dendy จะเปิดเอง (ต่ำกว่า 20 — พิกเซลใหญ่ขึ้น 120 เส้น) ปุ่ม \"กลับเป็นปกติ\" จะคืนกราฟิกปกติถาวร สิ่งที่คุณเลือกในเมนูมีผลก่อนเสมอ",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"โมเดล 3D ของสภาพแวดล้อม (ซากปรักหักพัง ซากยานพาหนะ ป้อมปราการ) — เฉพาะที่ได้คะแนนดี โหลดตามต้องการ ปิดได้ที่ ตั้งค่า → กราฟิก → \"โมเดลสภาพแวดล้อม 3D ใหม่\"",
