"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"ทหารราบสร้างได้: กด E (มือถือ \"เข้า\") ที่ไซต์ก่อสร้างฝ่ายเรา — ทหารจะสร้างเอง เพื่อนในหมู่ที่อยู่ใกล้ช่วยด้วย ถ้าวิศวกรไม่ว่าง นักยุทธศาสตร์จะขอให้คุณช่วย — มีเครื่องหมาย \"ไซต์ก่อสร้าง\"",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"หมุดนักยุทธศาสตร์: นักยุทธศาสตร์ปัก ⌖ บนกลุ่มศัตรูใกล้คุณ — ปืนใหญ่ยิงใส่หลังจาก 8 วินาที และ MLRS \"กราด\" ฝ่ายเราที่อยู่ใกล้จะยิงชุดสนับสนุน การระดมยิงปืนใหญ่ของคุณเองจากโหมดยุทธศาสตร์ก็ได้ \"กราด\" สนับสนุนเช่นกัน",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"ที่ซ่อนอาวุธในตู้คอนเทนเนอร์และดาวเทียมที่ตก (📦 มองเห็นในระยะ 70 ม.): กด E — ปืนกลหนัก 90 วินาที กระสุนเพลิงหรือจรวด พร้อมระเบิดมือเต็ม คลาน: Ctrl — นอนคว่ำ / ลุกขึ้น (ต่ำกว่า นิ่งกว่า เล็งแม่นกว่า แต่ช้า)",
