"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"จอยสติ๊กบนมือถือสามโหมด ยุทธศาสตร์แบบง่าย ประจำปืนยานพาหนะ ภูมิประเทศหุบเขา คลาสหมู่ วัตถุระเบิด",
