"last enemy nearby, tank, HQ":"ศัตรูคนสุดท้ายใกล้ๆ รถถัง กองบัญชาการ",
"corner; F7 — collapse":"ที่มุมจอ; F7 — ย่อ",
"Link copied":"คัดลอกลิงก์แล้ว",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ เล่นเลย\" — ปุ่มแรกของเมนู: บินผ่านใต้ท้องฟ้าประตูมิติสั้นๆ แล้วเข้าสู่การรบทันที (ข้ามได้ด้วยปุ่มใดก็ได้หรือการแตะ)",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"การยิงโดนให้ความรู้สึกจริง: เสียงโลหะและประกายไฟ เครื่องหมายสังหารที่เป้าเล็ง (ยิงหัว — สีเหลือง) สตรีค ×N กล้องสั่นนุ่มนวลจากการระเบิด สโลว์โมในการสังหารสำคัญ ปิดการสั่น สโลว์โม และคำแนะนำได้ในตั้งค่า",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"สรุปแมตช์: เวลา จำนวนที่ทำลาย สตรีคที่ดีที่สุด ★ MVP และหมู่ที่ดีที่สุด การ์ดแมตช์ — \"⇪ แชร์\" เป็น PNG หรือลิงก์เกม",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"คำแนะนำ \"ต้องทำอะไรตอนนี้\" ทางซ้ายใต้ทรัพยากร: คำสั่งนักยุทธศาสตร์ จุดที่ต้องยึด การรุกของฝูงแมลง ✕ หรือ F7 — ย่อ",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"การรบเซฟอัตโนมัติเมื่อปิดหรือซ่อนแท็บ — \"⟲ เล่นต่อ\" ในเมนู",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 ยังอยู่ในเมนู \"🕘 เวอร์ชันเกม\" เผื่อคุณชอบมากกว่า ตอนนี้ระบบส่งสถิติแบบไม่ระบุตัวตน (ไม่มีชื่อหรืออีเมล) ปิดได้ในตั้งค่า",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"เล่นเลย\" ฟีดแบ็กการยิงโดน สรุปแมตช์พร้อมการ์ดแชร์ คำแนะนำ \"ต้องทำอะไร\" เซฟอัตโนมัติ",
"and older: v7.5, v7.4, milestones v1–v7.0":"และเก่ากว่า: v7.5, v7.4, หมุดหมาย v1–v7.0",
"New in v7.6":"ใหม่ใน v7.6",
"NEW IN v7.6":"ใหม่ใน v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"เลือกฝ่ายก่อนแมตช์: \"คอนซอร์เทียม\" (ทหารราบหนักสวมเกราะพลัง เน้นเกราะและปืนใหญ่) หรือ \"สวอร์ม\" (ความเร็ว ฝูงโดรน ยิงหนักพร้อมการบิดเบือน) AI เล่นอีกฝ่าย ระบบจะจำที่คุณเลือก",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"แต่ละฝ่ายมียานพาหนะและของเฉพาะตัว: คอนซอร์เทียม — รถถัง \"ไรโน\" และ \"แผ่นเซรามิต\" สวอร์ม — \"ฝูงโดรน\" และ \"เจ็ตแพ็กเฟส\" ตรวจสอบสมดุลด้วยแมตช์ของบอทแล้ว",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"หลุมระเบิด: ปืนใหญ่ จรวด และปืนใหญ่รถถังขุดหลุมลงบนอุกกาบาต — เดินและขับผ่านได้ และหลบอยู่ข้างในได้",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"มุมมองบุคคลที่สามสำหรับทหารราบ (V, จำค่าไว้; บนมือถือ — ควบคุม) และกล้องยานพาหนะที่ลื่นไหล พร้อมเครื่องหมายจุดที่กระสุนปืนใหญ่จะตก",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 ยังอยู่ในเมนู \"🕘 เวอร์ชันเกม\" เผื่อคุณชอบเวอร์ชันนั้นมากกว่า",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"ฝ่ายคอนซอร์เทียม / สวอร์ม เลือกได้ก่อนแมตช์ หลุมระเบิด มุมมองบุคคลที่สาม",
"and older: v7.6, v7.5, milestones v1–v7.0":"และเวอร์ชันเก่า: v7.6, v7.5, หมุดหมาย v1–v7.0",
