"Recon: anomalies in the area, marked on the map":"สอดแนม: พบสิ่งผิดปกติในพื้นที่ ทำเครื่องหมายบนแผนที่แล้ว",
"Caution: anomaly right here!":"ระวัง: มีสิ่งผิดปกติอยู่ใกล้ๆ!",
