"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"กดนิ้วค้างบนพื้นราว 0.3 วิ — มือถือสั่นและมีวงแหวนเหลืองปรากฏ — แล้วลากโดยไม่ยกนิ้ว: จะได้กรอบเลือก หรือใช้ปุ่ม \"กรอบ\" ด้านขวา แตะเลือกหมู่ก็ได้เหมือนกัน",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"เต็มจอบน iPhone: \"แชร์\" ⬆ → \"เพิ่มลงในหน้าจอโฮม\" — เกมจะเปิดโดยไม่มีแถบของ Safari",
"Open portal-meteor.pages.dev for that.":"เปิดเว็บ portal-meteor.pages.dev เพื่อทำแบบนั้น",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"แตะ — เลือก · แตะพื้น — เดิน · แตะค้าง — เมนูคำสั่ง · แตะค้างแล้วลาก — กรอบ · 2 นิ้ว — ซูม",
"Robo-ninja":"หุ่นยนต์นินจา",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"ฮีโร่นักลอบสังหาร: พุ่งเทเลพอร์ต ดาบคาตานะ ชูริเกน เทเลพอร์ตข้ามโซนศัตรูเอง และฟันหุ่นยนต์เป็นชิ้นๆ ฝ่ายละ 1",
"Shadow protocol":"โปรโตคอล \"เงา\"",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"วิจัย: ปลดล็อกหุ่นยนต์นินจาในค่ายทหาร ต้องมีโรงงานเมคที่สร้างเสร็จ",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"ฮีโร่ (ฝ่ายละ 1): เทเลพอร์ตข้ามโซนศัตรูเองและฟันหุ่นยนต์เป็นชิ้นๆ ควบคุมเธอเพื่อเล่นเองได้",
"is ready. She works on her own (AUTO) — possess her to play manually":"พร้อมแล้ว ทำงานเอง (อัตโนมัติ) — ควบคุมเธอเพื่อเล่นเอง",
"Robo-ninja ready for action":"หุ่นยนต์นินจาพร้อมรบ",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ สอดแนม: ศัตรูมีหุ่นยนต์นินจา!",
"Warning! The enemy has a robo-ninja. Stay together":"ระวัง! ศัตรูมีหุ่นยนต์นินจา อยู่รวมกันไว้",
"cyber blinks":"พุ่งไซเบอร์",
"Too far for a dash — get closer or teleport":"ไกลเกินพุ่ง — เข้าไปใกล้กว่านี้หรือเทเลพอร์ต",
