"enemy group":"กลุ่มศัตรู",
"order":"คำสั่ง",
"nearby":"ใกล้ๆ",
"Zone cleared":"ล้างโซนแล้ว",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ ดวลนินจา! บล็อกก่อนโดนตีเพื่อปัดป้อง พุ่งเพื่อหลบ ดูแสงวาบตอนง้างอาวุธ",
"The two ninjas have met in a duel!":"นินจาสองคนมาดวลกัน!",
"⚔ Duel won! Our ninja prevails":"⚔ ชนะการดวล! นินจาของเราเหนือกว่า",
"⚔ Duel lost…":"⚔ แพ้การดวล…",
"ninja duel":"ดวลนินจา",
"POSTURE BROKEN":"ท่าทางพัง",
"Teleport":"เทเลพอร์ต",
"Teleport: aim at the ground (up to 150 m)":"เทเลพอร์ต: เล็งไปที่พื้น (ไกลสุด 150 ม.)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ อัตโนมัติ: กระโดดข้ามโซนศัตรูและฟันเอง จอยสติ๊ก / WASD หยุดชั่วคราว 1.5 วิ",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ ควบคุมเอง: แตะที่ศัตรู — พุ่งและฟัน ปัด — ฟาดดาบ 🛡 — บล็อก",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ ควบคุมเอง: คลิกซ้าย — คาตานะ คลิกขวา — บล็อก Shift — พุ่ง Q — shuriken G — เทเลพอร์ต",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ นินจา: แตะที่ศัตรู — พุ่งเข้าฟัน, ปัดทางขวา — ฟาด, ● — โจมตี, 🛡 — ป้องกัน (จังหวะพอดี = ปัดป้อง), ⇑ — พุ่งหลบ, ✦ — ชูริเกน, ◎ — เทเลพอร์ต, AUTO — ให้เธอเล่นเอง",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ นินจา: คลิกซ้าย — คาตานะ (ค้าง — ฟันหนัก), คลิกขวา — ป้องกัน (จังหวะพอดี = ปัดป้อง), Shift/Z — พุ่งหลบ, Q — ชูริเกน, G — เทเลพอร์ตไปที่เป้าเล็ง, กระโดดกลางอากาศ — กระโดดสองชั้น / วิ่งบนกำแพง, {0} — AUTO",
"Robo-ninja: AUTO on/off":"หุ่นยนต์นินจา: AUTO เปิด/ปิด",
"Disabled":"ปิดใช้งาน",
"Requires a finished Mech factory":"ต้องมีโรงงานเมคที่สร้างเสร็จแล้ว",
