"LMB — strike (hold — heavy) · RMB — block · Shift — blink · Q — shurikens · G — teleport":"คลิกซ้าย — โจมตี (ค้าง — ฟันหนัก) · คลิกขวา — ป้องกัน · Shift — พุ่งหลบ · Q — ชูริเกน · G — เทเลพอร์ต",
