"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"วิทยุ Portal Meteor: เพลงกว่า 100 เพลงของ EDMITRY ในเกม — ปุ่ม 📻 (PC: ปุ่ม 5, [ ] — เปลี่ยนเพลง) เพลงสตรีมเมื่อเปิดฟังจึงไม่ทำให้เกมหนักขึ้น ปรับระดับเสียงและเปิดอัตโนมัติได้ในตั้งค่า พร้อมลิงก์ \"ฟังบน Spotify\"",
