"on/off":"เปิด/ปิด",
"track":"เพลง",
"Radio":"วิทยุ",
"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"วิทยุ Portal Meteor เปิด/ปิด ([ ] — เปลี่ยนเพลง, Shift+[ ] — ระดับเสียง)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 ทางขวา — วิทยุ Portal Meteor: ฟังเพลงของ EDMITRY ขณะต่อสู้",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — วิทยุ Portal Meteor: ฟังเพลงของ EDMITRY ขณะต่อสู้ [ ] — เปลี่ยนเพลง",
"Radio Portal Meteor (EDMITRY): volume":"วิทยุ Portal Meteor (EDMITRY): ระดับเสียง",
"Radio: start by itself in battle":"วิทยุ: เปิดเองเมื่อเข้าต่อสู้",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"หุ่นยนต์นินจา: ไซบอร์กถือคาตานะ ปลดล็อกที่ค่ายทหารด้วยการวิจัย \"โปรโตคอลเงา\" (ต้องมีโรงงานเมค) เทเลพอร์ตเข้าโซนศัตรูเอง ฟันศัตรูขาดเป็นท่อน (ไม่มีเลือด — มีแต่ประกายไฟ) พุ่งหลบ ขว้างชูริเกน ดวลกับนินจาฝ่ายศัตรู ควบคุมเธอได้ — โหมด AUTO หรือควบคุมเอง (บนมือถือมีปุ่มของตัวเอง)",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"วิทยุ Portal Meteor: เพลงของ EDMITRY 103 เพลงในเกม ปุ่ม 5 (เปลี่ยนปุ่มได้) บนมือถือ — ☰ → ตั้งค่า → เสียง ปรับระดับเสียงและ \"เปิดเองเมื่อเข้าต่อสู้\" ได้ในตั้งค่า เพลงจะเบาลงเมื่อมีระเบิดและเสียงวิทยุสื่อสาร",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"ภาษาใหม่: อุซเบกและทาจิก — แปลครบ จีน สเปน โปรตุเกส — แปลบางส่วน มีตัวเลือกภาษาใหม่ในเมนูข้างปุ่ม \"แมตช์ใหม่\"",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"มือถือ: \"ซ่อนไอคอน\" 👁 รวมปุ่มที่เหลือเป็นแถวเรียบร้อยที่ขอบขวา แนวตั้งไม่ทับกันอีกแล้ว iPhone — เกมไม่ชนกับท่าทางของ Safari และ \"แชร์ → เพิ่มลงหน้าจอโฮม\" จะเปิดแบบเต็มจอ",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"จาก v7.8.1: เมนู ☰ ที่มุม (พัก, เริ่มใหม่, ฝึกซ้อม, กราฟิก) ไม่สลับ Dendy อัตโนมัติ ปุ่มทำงาน ✋ บนมือถือ v7.8.1 และ v7.8 ยังอยู่ในเมนู \"🕘 เวอร์ชันเกม\"",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"หุ่นยนต์นินจา, วิทยุ EDMITRY, อุซเบกและทาจิก, ใช้งานมือถือและ iPhone สะดวกขึ้น",
