"Squad {0} is lost — its veterancy (lv {1}) is gone. See \"My squads → Fallen\".":"หมู่ {0} สูญสิ้นแล้ว — ยศทหารผ่านศึก (ระดับ {1}) หายไป ดูได้ที่ \"หมู่ของฉัน → ผู้พลีชีพ\"",
