"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"เลือกยูนิต → \"▶ สิงร่าง\" หรือคลิกสองครั้ง {0} — วนรอบ: นักยุทธศาสตร์ → ผู้บัญชาการ → นักยิง",
