"Living world: requests, hero quests, breakthrough ops":"โลกมีชีวิต: คำขอ, เควสต์ฮีโร่, ปฏิบัติการจุดเปลี่ยนศึก",
"Living world":"โลกมีชีวิต",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"พวกเดียวกันขอความช่วยเหลือและตอบแทนคุณ ฮีโร่ให้เควสต์ แนวหน้าที่ยืดเยื้อจะถูกทลายด้วยปฏิบัติการ",
"A request":"คำขอ",
"Breakthrough":"จุดเปลี่ยนศึก",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"บางครั้งพวกเดียวกันจะขอความช่วยเหลือ: เสียงทางวิทยุ การ์ด \"ขอความช่วยเหลือ\" และเครื่องหมาย ✋ หมู่ถูกตรึง — ทำลายศัตรูใกล้ๆ หมู่นั้น รางวัล: ทหารราบมาทางแคปซูลจากฐาน, ปืนจากท้ายรถบั๊กกี้, ที่นั่งพลปืน หรือการคุ้มกันจากวงโคจร ไม่อยากรับ — ✕ หรือเมินไปเลย",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"\"ซื่อ\" หน่วยสอดแนมเก๋าเกมเสนอเควสต์ Y — รับ (N — ปฏิเสธ) ไปที่เครื่องหมาย ★ กำจัดยามแล้วยืนข้างนักบิน 3 วิ — เขาจะเข้าหมู่คุณ",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"แนวหน้าติดหล่ม — กองบัญชาการเสนอปฏิบัติการจุดเปลี่ยนศึก Y — รับ ยึดรีเลย์ไว้ 8 วิโดยไม่มีศัตรูอยู่ใกล้: เห็นแผนที่ศัตรู 60 วิ เครื่องกำเนิดไฟฟ้า — ป้อมปืนศัตรูเงียบ 2 นาที ในโหมดนักยุทธศาสตร์ — \"มอบหมู่\" ศัตรูก็ทำได้เหมือนกัน: ระวัง ⚠",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"พวกเดียวกันขอความช่วยเหลือ: การ์ด \"ขอความช่วยเหลือ\" และเครื่องหมาย ✋ ทำลายศัตรูใกล้หมู่ที่ถูกตรึงเพื่อรับรางวัล ✕ — ข้าม",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"ฮีโร่ \"ซื่อ\" เสนอเควสต์ — แตะ \"รับ\" ไปที่ ★ กำจัดยาม ยืนข้างนักบิน",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"แนวหน้าติดหล่ม — แตะ \"รับ\" แล้วยึดรีเลย์ไว้ 8 วิ: แผนที่ศัตรูจะเปิดหนึ่งนาที",
