"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. เล่นไปพูดไป: อะไรที่งง อะไรที่น่ารำคาญ อะไรที่สนุก มุมจอแสดงเวอร์ชัน เวลา และ FPS — ใช้จับคู่คลิปกับบันทึก",
